INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('5efde8cc-d689-5711-9be7-5929032b9a53', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$briefing-compose$SR$, $SR$Verify: facts, gaps, sources$SR$, $SR${"timezone": "Europe/London", "titlePrefix": "Briefing", "auditRun": true}$SR$::jsonb, $SR${"x": 1600, "y": 380}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('dc7493f0-96f7-5c38-8358-d89e45f0be89', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$llm-call$SR$, $SR$Write the summary$SR$, $SR${"model": "", "systemPrompt": "You write John's morning briefing from a pre-verified FACTS block.\n\nABSOLUTE RULES \u2014 these override every other instruction:\n1. Every number, place name, time, temperature and condition you write MUST appear verbatim in FACTS. Never compute, convert, round, estimate or infer a value.\n2. Units in FACTS are already correct (Celsius, km/h, km). NEVER convert them \u2014 do not output Fahrenheit or miles.\n3. Anything named in GAPS is unavailable. You may state it is unavailable, or omit it entirely. You must NEVER substitute a plausible-sounding value for it.\n4. If FACTS is empty, reply with exactly one line saying no data was available, and stop.\n5. Never invent an email subject, a meeting, an alert, or a health number.\n\nSTYLE: 3 to 6 bullet points, most important first, each under 25 words. Lead with anything under 'Local factors'. If he is not at home, say where he is and how the weather there differs from home. No preamble, no sign-off, no headings.", "userPrompt": "Today is {{input.briefing.dateLabel}}.\n\nFACTS\n{{input.factSheet}}\n\nGAPS\n{{input.gapSheet}}", "temperature": 0.2, "maxTokens": 2000}$SR$::jsonb, $SR${"x": 1860, "y": 380}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('037b85f4-3707-5c5a-8592-df2b8873ecdf', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$transform$SR$, $SR$Build record + message$SR$, $SR${"expression": "const b = input.briefing || {};\nconst md = (input.response || '').trim();\nconst gaps = input.gaps || [];\nconst sources = input.sources || [];\nconst ok = sources.filter(function (s) { return s.status === 'ok'; });\nconst now = new Date().toISOString();\nconst record = {\n  id: b.date,\n  trigger: 'workflow',\n  status: 'complete',\n  startedAt: b.generatedAt || now,\n  finishedAt: now,\n  title: b.title || 'Briefing',\n  markdown: md,\n  sources: ok.map(function (s) { return s.key; }),\n  llmCalls: 1,\n  costUsd: 0,\n  detail: {\n    headline: b.headline || '',\n    dateLabel: b.dateLabel || '',\n    generatedAt: b.generatedAt || now,\n    timezone: b.timezone || 'Europe/London',\n    location: b.location || null,\n    weather: b.weather || null,\n    knowledge: b.knowledge || null,\n    facts: input.facts || [],\n    gaps: gaps,\n    sources: sources\n  }\n};\nconst lines = ['\\u2615 ' + record.title];\nif (b.headline) lines.push(b.headline);\nif (md) { lines.push(''); lines.push(md); }\nif (gaps.length) {\n  lines.push('');\n  lines.push('\\u26a0 No data: ' + gaps.map(function (g) { return g.section; }).join(', '));\n}\nlines.push('');\nlines.push('Full detail: https://strangeramblings.com/jkai/briefing');\nreturn { record: record, recordKey: record.id, whatsapp: lines.join('\\n') };"}$SR$::jsonb, $SR${"x": 2120, "y": 380}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('0fffbaf6-7c63-542b-92ae-d9002c117e70', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$database$SR$, $SR$Save briefing detail$SR$, $SR${"operation": "upsert", "collection": "briefings", "autoCreate": true, "key": "{{input.recordKey}}", "data": "{{input.record}}"}$SR$::jsonb, $SR${"x": 2380, "y": 300}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('680d27d2-ea7a-5688-b460-ba36bec9714d', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$whatsapp$SR$, $SR$Send summary$SR$, $SR${"to": "+447359228511", "message": "{{input.whatsapp}}", "formatMarkdown": true, "maxChunks": 3}$SR$::jsonb, $SR${"x": 2380, "y": 460}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('258c8729-84bd-59ea-84cb-d14a8442361e', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$postit$SR$, $SR$How this stays honest$SR$, $SR${"title": "Why this cannot fabricate", "color": "yellow", "text": "Every source is namespaced by its own transform, so the LLM sees which data came from where (the old version pasted one merged blob under four different headings and let the model guess).\n\nbriefing-compose turns those signals into a FACTS block of pre-formatted, unit-correct values plus an explicit GAPS list. The LLM may only quote FACTS verbatim and must never fill a GAP.\n\nFailed sources are recorded in the source ledger with their real error and shown on /jkai/briefing \u2014 they are never silently skipped."}$SR$::jsonb, $SR${"x": 2380, "y": 620}$SR$::jsonb);
